<template>
  <q-page class="customer-flow-page"><div class="page-heading"><div><div class="eyebrow">{{ auth.isCustomer ? 'EVERYDAY BANKING' : 'OPERATIONS' }}</div><h1 class="page-title">{{ auth.isCustomer ? 'Deposits & withdrawals' : 'Customer requests' }}</h1><p class="page-subtitle">{{ auth.isCustomer ? 'Submit a request for staff review. Balances change only after approval.' : 'Review and process simulated branch requests.' }}</p></div><q-btn flat icon="refresh" label="Refresh" @click="load" /></div><q-banner v-if="error" class="bg-red-1 text-red-9 q-mb-md">{{ error }}</q-banner>
    <div :class="auth.isCustomer ? 'customer-workspace-grid' : ''"><section v-if="auth.isCustomer" class="customer-panel"><h2 class="section-heading">New request</h2><q-form ref="requestForm" class="customer-form" @submit="submit"><q-select v-model="form.account_id" filled label="Account" emit-value map-options :options="accounts.map(a => ({ label: a.account_number, value: a.id }))" :rules="[v => !!v || 'Choose an account']" /><q-select v-model="form.kind" filled label="Request type" :options="['DEPOSIT', 'WITHDRAWAL']" /><q-input v-model="form.amount" filled type="number" min="0.01" step="0.01" label="Amount (PHP)" :rules="[v => Number(v) > 0 || 'Enter a positive amount']" /><q-input v-model="form.note" filled maxlength="250" label="Note (optional)" /><q-btn color="primary" label="Submit request" type="submit" :loading="busy" :disable="loading" /></q-form></section>
    <section class="customer-panel"><h2 class="section-heading">Request history</h2><q-table flat :rows="rows" :columns="columns" row-key="id" :loading="loading" :pagination="{ rowsPerPage: 8 }"><template #body-cell-status="p"><q-td :props="p"><q-badge :color="p.row.status === 'APPROVED' ? 'positive' : p.row.status === 'PENDING' ? 'warning' : 'negative'">{{ p.row.status }}</q-badge></q-td></template><template #body-cell-review="p"><q-td :props="p"><template v-if="p.row.status === 'PENDING' && !auth.isCustomer"><q-btn flat color="positive" label="Approve" :disable="busy" @click="review(p.row, 'APPROVED')" /><q-btn flat color="negative" label="Reject" :disable="busy" @click="review(p.row, 'REJECTED')" /></template></q-td></template></q-table></section></div>
    <AccountApplications />
  </q-page>
</template>
<script setup>
import { ref, computed, onMounted, nextTick } from 'vue'
import { useQuasar } from 'quasar'
import { useAuthStore } from '@/stores/auth-store'
import api from '@/services/api'
import AccountApplications from '@/components/AccountApplications.vue'
const auth = useAuthStore(), $q = useQuasar(), rows = ref([]), accounts = ref([]), loading = ref(false), busy = ref(false), error = ref('')
const requestForm = ref(null)
const form = ref({ account_id: null, kind: 'DEPOSIT', amount: '', note: '' })
const columns = computed(() => [{ name: 'reference', field: 'reference', label: 'Reference', align: 'left' }, { name: 'kind', field: 'kind', label: 'Type', align: 'left' }, { name: 'amount', field: 'amount', label: 'PHP', align: 'right', format: v => Number(v).toLocaleString('en-PH', { minimumFractionDigits: 2 }) }, { name: 'status', field: 'status', label: 'Status', align: 'left' }, ...(!auth.isCustomer ? [{ name: 'review', label: 'Review', field: 'id' }] : [])])
async function load () { loading.value = true; error.value = ''; try { rows.value = (await api.get(auth.isCustomer ? '/customer/requests/' : '/banking-requests/')).data; if (auth.isCustomer) accounts.value = (await api.get('/customer/accounts/')).data.filter(a => a.status === 'ACTIVE') } catch { error.value = 'Could not load requests. Please retry.' } finally { loading.value = false } }
async function submit () { if (busy.value) return; busy.value = true; try { await api.post('/customer/requests/', form.value); form.value = { account_id: null, kind: 'DEPOSIT', amount: '', note: '' }; await nextTick(); requestForm.value?.resetValidation(); await load(); $q.notify({ type: 'positive', message: 'Request submitted for review' }) } catch (e) { $q.notify({ type: 'negative', message: typeof e.response?.data?.detail === 'string' ? e.response.data.detail : 'Could not submit request' }) } finally { busy.value = false } }
function review (row, status) { $q.dialog({ title: status === 'APPROVED' ? 'Approve this request?' : 'Reject this request?', message: `${row.kind} · PHP ${row.amount} · ${row.reference}. Approval updates the simulated balance.`, cancel: true, persistent: true }).onOk(async () => { busy.value = true; try { await api.post(`/banking-requests/${row.id}/review`, { status }); await load() } catch (e) { $q.notify({ type: 'negative', message: e.response?.data?.detail || 'Could not process request' }) } finally { busy.value = false } }) }
onMounted(load)
</script>
